}.ev-m {

  --font-serif: 'EV Newsreader', 'Newsreader', 'Newsreader Fallback', Georgia, 'Times New Roman', serif;
  --font-sans: 'EV Hanken Grotesk', 'Hanken Grotesk', 'Hanken Grotesk Fallback', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-brand: 'EV Hanken Grotesk', 'Hanken Grotesk', 'Hanken Grotesk Fallback', system-ui, sans-serif;


  --green-950: #0A1F16;
  --green-900: #0F2A20;
  --green-800: #203A37;
  --green-700: #0E1113;
  --green-600: #314743;
  --green-500: #3E8556;
  --green-400: #B8875A;


  --seafoam-300: #AED7C7;
  --seafoam-100: #D6EBE2;
  --seafoam-50:  #F1EEE7;


  --sand-50:  #F1EEE7;
  --sand-100: #E7E3DA;
  --sand-200: #E7E0D1;
  --sand-300: #D4C9B5;
  --sand-400: #B5A88F;


  --danger-500: #C82414;
  --danger-600: #B01F11;


  --color-primary: #0E1113;
  --color-primary-hover: #203A37;
  --color-on-primary: #FFFFFF;


  --text-primary:   #1E2A23;
  --text-secondary: #4A574F;
  --text-muted:     #7C887F;
  --text-brand:     #314743;
  --text-on-dark:       rgba(255,255,255,.90);
  --text-on-dark-muted: rgba(255,255,255,.66);
  --ink-900: #14201A;
  --white:   #FFFFFF;


  --color-canvas:  #FCFBF7;
  --color-surface: #FFFFFF;
  --border-subtle:  #ECE7DB;
  --border-default: #DED7C7;
  --border-strong:  #C7BFAD;


  --text-lg: 18px;


  --accent: #0E1113;
  --accent-strong: #0E1113;
  --accent-hover: #203A37;
  --accent-on: #FFFFFF;
  --accent-tint: #F1EEE7;
}
.ev-m [data-accent="neutral"] {
  --accent: #0E1113;
  --accent-strong: #0E1113;
  --accent-hover: #203A37;
  --accent-on: #FFFFFF;
  --accent-tint: #F1EEE7;
}
.ev-m [data-accent="male"] {
  --accent: #C67E57;
  --accent-strong: #C67E57;
  --accent-hover: #B26B45;
  --accent-on: #FFFFFF;
  --accent-tint: #F4E4DA;
}
.ev-m [data-accent="female"] {
  --accent: #F6D9E1;
  --accent-strong: #B05A78;
  --accent-hover: #EFC9D5;
  --accent-on: #8A3D5A;
  --accent-tint: #F6D9E1;
}
.ev-m, .ev-m *, .ev-m *::before, .ev-m *::after { box-sizing: border-box; }
.ev-m { scroll-behavior: smooth; }
.ev-m {
    margin: 0;
    background: var(--color-canvas);
    color: var(--text-primary);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
  }
.ev-m .wrap { max-width: 1200px; margin: 0 auto; padding: 0 40px; }
