.ev-m .foot-col { border-top: 1px solid var(--green-800); }
.ev-m .foot-col:last-child { border-bottom: 1px solid var(--green-800); }
.ev-m .foot-col h4.foot-toggle { margin: 0; padding: 17px 2px; cursor: pointer; font-size: 12.5px; }
.ev-m .fic { display: block; position: relative; width: 12px; height: 12px; flex: none; }
.ev-m .fic::before, .ev-m .fic::after { content: ""; position: absolute; background: var(--seafoam-300); transition: transform .25s ease, opacity .25s ease; }
.ev-m .fic::before { top: 5px; left: 0; width: 12px; height: 2px; }
.ev-m .fic::after { left: 5px; top: 0; width: 2px; height: 12px; }
.ev-m .foot-col.open .fic::after { transform: scaleY(0); opacity: 0; }
.ev-m .foot-links { overflow: hidden; max-height: 0; opacity: 0; transition: max-height .3s ease, opacity .2s ease; }
.ev-m .foot-col.open .foot-links { padding-bottom: 8px; }
