      html {
        -webkit-box-sizing: border-box;
        -moz-box-sizing: border-box;
        box-sizing: border-box;
      }
    *, *:before, *:after {
      -webkit-box-sizing: inherit;
      -moz-box-sizing: inherit;
      box-sizing: inherit;
      }
      :host {
            --compliance-theme: #00B67A;
            --compliance-position-top: unset;
            --compliance-position-left: 10px;
            --compliance-position-right: unset;
            --compliance-position-bottom: 10px;
            --compliance-transform-vertical: 0px;
            --compliance-transform-horizontal: 0px;
            --compliance-border-radius: 0px;
            --compliance-default-hidden: hidden;
            --compliance-default-hidden-cookie: hidden;
        }
        /* Mandatory (locked) toggles.
         *
         * createSwitchList renders a locked category as 'disabled checked', so it
         * must read as ON-but-not-editable. These rules used to force the track to
         * rgb(229 231 235) -- the exact grey the template uses for the OFF track --
         * which told the visitor that strictly necessary cookies were off while
         * consent actually had them granted. The state was right, the paint was not.
         *
         * The colour is derived from the operator's theme instead of a hardcoded
         * blue, so it stays on-brand for non-blue themes; browsers without
         * color-mix() keep the solid theme declaration above it, which still reads
         * as ON. 65% theme keeps the hue readable for colour themes and stays
         * clearly darker than the OFF track for near-monochrome ones (the default
         * theme is #1d2128): mixing in more white turns those back into a grey
         * that reads as off, which is the bug this replaces. Keyed on :disabled rather than on #STRICTLY_NECESSARY_COOKIES so
         * bucket-mode locked toggles -- whose id is the bucket id, not the category
         * name -- get the same treatment. 'disabled' implies checked everywhere in
         * this file (isChecked = isDisabled || switchStatus), so the knob is pinned
         * to the right here too: a locked toggle can never paint as off, even if a
         * later pass fails to re-check it.
         *
         * !important is kept from the rules this replaces: the template CSS and any
         * operator-authored settingsCss are injected AFTER this block.
         */
        .captain-compliance-modal-settings-body_content_switch_list_item .captain-compliance-modal-settings-body_content_switch_list_item_preset input:disabled + label {
          background-color: var(--compliance-theme, #1d2128) !important;
          background-color: color-mix(in srgb, var(--compliance-theme, #1d2128) 65%, #ffffff) !important;
          cursor: not-allowed !important;
        }
        .captain-compliance-modal-settings-body_content_switch_list_item .captain-compliance-modal-settings-body_content_switch_list_item_preset input:disabled + label:after {
          left: calc(100% - 3px) !important;
          transform: translateX(-100%) !important;
        }
        .captain-compliance-modal-settings-body_content_switch_list_item .captain-compliance-modal-settings-body_content_switch_list_item_preset input:disabled + label:hover:after {
          width: 16px !important;
        }
        #captain-compliance-modal-overlay {
          visibility: hidden;
          position: fixed; 
          z-index: 99; 
          height: 100%; 
          width: 100%; 
          top: 0; left: 0; 
          background: black; 
          opacity: 0;
        }
        h1, h2, h3, h4, p {
          margin: 0;
        }

