#evlv-landing-content .path-opts .opt{display:flex!important;align-items:center!important;gap:12px!important;cursor:pointer!important}
@media (max-width:767px){#evlv-landing-content .path-opts{grid-template-columns:1fr!important}}

#evlv-landing-content .product .shop-btn{display:block;margin-top:14px;padding:12px 18px;border-radius:999px;background:#FFFFFF;border:1px solid var(--color-copper, #B8875A);color:#1c2224;text-align:center;font-weight:600;font-size:14px;letter-spacing:.01em;transition:background .18s ease,color .18s ease;}
#evlv-landing-content .product:hover .shop-btn{background:var(--color-copper, #B8875A);color:#1c2224;}

#evlv-landing-content .biomarq-track{animation:bioScroll 46s linear infinite!important;animation-play-state:running!important}

/* EVLV override: real button styling for the featured-products "View Compound" CTA -- was a full-pill copper background on hover, which reads oversized/odd and puts copper (an accent color, not a CTA color per the brand spec) as a solid fill. Now a proper rounded-rectangle outline button matching the site's real secondary-button style (charcoal border/text, inverts to solid charcoal on hover). */
#evlv-landing-content .product .shop-btn{display:block!important;margin-top:14px!important;padding:12px 20px!important;border-radius:10px!important;background:#FFFFFF!important;border:1.5px solid #0E1113!important;color:#0E1113!important;text-align:center!important;font-weight:600!important;font-size:13px!important;letter-spacing:.04em!important;text-transform:uppercase!important;transition:background .18s ease,color .18s ease,border-color .18s ease!important;}
#evlv-landing-content .product:hover .shop-btn{background:#0E1113!important;border-color:#0E1113!important;color:#E7E3DA!important;}

/* EVLV override: force the homepage's .ev-d content to stay visible on mobile -- the scraped source's own stylesheet hides `.ev-d` below 767px (`@media (max-width:767px){.ev-d{display:none!important}}`), expecting a separate `.ev-m` mobile variant to take over. That mobile variant was never ported into this codebase, so on any phone-width screen the entire homepage content was hidden with nothing to replace it -- the page rendered completely blank. This ID-scoped rule outranks that class-scoped one and forces the real content to stay visible at every width. */
@media (max-width:767px){#evlv-landing-content.ev-d{display:block!important}}

@media (max-width: 480px) {
  .ev-d .hero-tiles { gap: 10px; }
  .ev-d .hero-tile .go svg { width: 13px; height: 13px; }
}

/* Deal of the Day / Giveaway rows -- same .hero-row shell as the other two
   category rows, just with a second small line under the title so price/
   countdown or prize/entry-count copy fits without changing the row's
   height or breaking its layout. */
.hero-row-sub {
  display: block;
  margin-top: 3px;
  font-family: var(--font-sans, inherit);
  font-size: 0.78rem;
  font-weight: 500;
  color: #7E8780;
  letter-spacing: 0;
}
.hero-row-sub s { opacity: 0.6; font-weight: 400; margin-left: 4px; }
.hero-row-sub .accent { color: var(--danger-500, #C82414); font-weight: 600; }

.ev-d .fmt-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; }
.ev-d .fmtcard { position: relative; aspect-ratio: 3 / 4; border-radius: 16px; overflow: hidden; display: flex; align-items: flex-end; text-decoration: none; transition: transform .2s ease; }
.ev-d .fmtcard:hover { transform: translateY(-3px); }
.ev-d .fmtcard .gimg { position: absolute; inset: 0; }
.ev-d .fmtcard .gimg img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s ease; }
.ev-d .fmtcard:hover .gimg img { transform: scale(1.06); }
.ev-d .fmtcard .sc { position: absolute; inset: 0; background: linear-gradient(0deg, rgba(15,42,32,.92), rgba(15,42,32,.22) 60%, rgba(15,42,32,0) 85%); }
.ev-d .fmtcard .lbl { position: relative; z-index: 2; padding: 18px; width: 100%; }
.ev-d .fmtcard .eyebrow-sm { margin: 0 0 4px; font-family: var(--font-brand); font-size: 10.5px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--seafoam-300); }
.ev-d .fmtcard h3 { font-family: var(--font-serif); font-weight: 400; font-size: 1.2rem; margin: 0; color: var(--white); letter-spacing: -0.01em; }
.ev-d .fmtcard .fsub { margin: 6px 0 0; font-size: 12.5px; line-height: 1.4; color: rgba(255,255,255,.78); }
@media (max-width: 900px) { .ev-d .fmt-grid { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 600px) { .ev-d .fmt-grid { grid-template-columns: repeat(2, 1fr); } }

script:
(function(){
  // Functional link/image fixups carried over from the source scrape --
  // not text-compliance swaps, just repairing hrefs/lazy-image fallbacks.
  function run(){
    document.querySelectorAll('a[href*="treatments"],a[href*="peptide-splash"]').forEach(function(a){ a.href = '/shop'; });
    document.querySelectorAll('img[data-savepage-src]').forEach(function(i){ if (!i.getAttribute('src')) i.src = i.dataset.savepageSrc; });
  }
  run(); setTimeout(run, 300); setTimeout(run, 1000);
})();


(function(){
  // ---- carousel prev/next buttons ----
  function wireCarousel(prefix){
    var track = document.getElementById(prefix + '-track');
    var prevBtn = document.getElementById(prefix + '-prev');
    var nextBtn = document.getElementById(prefix + '-next');
    if (!track || track.dataset.wired) return;
    track.dataset.wired = '1';
    function amount(){
      var c = track.firstElementChild;
      var w = c ? c.getBoundingClientRect().width : 300;
      return w + 24;
    }
    function update(){
      if (prevBtn) prevBtn.disabled = track.scrollLeft <= 4;
      if (nextBtn) nextBtn.disabled = track.scrollLeft >= track.scrollWidth - track.clientWidth - 4;
    }
    if (prevBtn) prevBtn.addEventListener('click', function(){ track.scrollBy({ left: -amount(), behavior: 'smooth' }); });
    if (nextBtn) nextBtn.addEventListener('click', function(){ track.scrollBy({ left: amount(), behavior: 'smooth' }); });
    track.addEventListener('scroll', update, { passive: true });
    update();
  }
  function wireAllCarousels(){ ['car', 'goal'].forEach(wireCarousel); }
  wireAllCarousels(); setTimeout(wireAllCarousels, 300); setTimeout(wireAllCarousels, 1000);

  // ---- FAQ accordion ----
  function wireFaq(){
    document.querySelectorAll('.faq-item').forEach(function(item){
      if (item.dataset.wired) return;
      item.dataset.wired = '1';
      var btn = item.querySelector('.faq-q');
      var body = item.querySelector('.faq-a');
      if (!btn || !body) return;
      btn.addEventListener('click', function(){
        var isOpen = item.classList.contains('open');
        document.querySelectorAll('.faq-item.open').forEach(function(other){
          if (other !== item) { other.classList.remove('open'); var ob = other.querySelector('.faq-a'); if (ob) ob.style.maxHeight = ''; }
        });
        if (isOpen) { item.classList.remove('open'); body.style.maxHeight = ''; }
        else { item.classList.add('open'); body.style.maxHeight = body.scrollHeight + 'px'; }
      });
    });
  }
  wireFaq(); setTimeout(wireFaq, 300); setTimeout(wireFaq, 1000);

  // ---- "Find your path" pills open the real quiz widget instead of jumping straight to /shop ----
  function wireQuizPills(){
    document.querySelectorAll('.path-opts .opt').forEach(function(a){
      if (a.dataset.wired) return;
      a.dataset.wired = '1';
      a.addEventListener('click', function(e){
        e.preventDefault();
        window.dispatchEvent(new Event('evlv:open-quiz'));
      });
    });
  }
  wireQuizPills(); setTimeout(wireQuizPills, 300); setTimeout(wireQuizPills, 1000);

  // ---- batch verify widget -> real /coas lookup ----
  function wireBatchVerify(){
    var btn = document.getElementById('evlvBatchVerify');
    var input = document.getElementById('evlvBatchCode');
    var result = document.getElementById('evlvBatchResult');
    if (!btn || btn.dataset.wired) return;
    btn.dataset.wired = '1';
    btn.addEventListener('click', function(){
      var code = (input && input.value || '').trim();
      if (!code) { if (result) result.textContent = 'Enter a batch code first'; return; }
      window.location.href = '/coas?search=' + encodeURIComponent(code);
    });
    if (input) {
      input.addEventListener('keydown', function(e){ if (e.key === 'Enter') btn.click(); });
    }
  }
  wireBatchVerify(); setTimeout(wireBatchVerify, 300); setTimeout(wireBatchVerify, 1000);
})();


(function(){
  // Animated COA purity ring: counts up to a real batch purity figure and
  // fills the arc to match, instead of the static everlifemd patient-metric
  // donut ("64% in Optimal Range") that shipped in the source markup.
  var TARGET = 99.87;
  var CIRCUMFERENCE = 301.59;
  function animate(widget){
    if (widget.dataset.animated) return;
    widget.dataset.animated = '1';
    var arc = widget.querySelector('.purity-arc');
    var label = widget.querySelector('.purity-value');
    if (!arc || !label) return;
    arc.style.transition = 'stroke-dashoffset 1.4s cubic-bezier(.16,1,.3,1)';
    requestAnimationFrame(function(){
      arc.style.strokeDashoffset = String(CIRCUMFERENCE * (1 - TARGET / 100));
    });
    var start = null;
    var duration = 1400;
    function step(ts){
      if (!start) start = ts;
      var p = Math.min((ts - start) / duration, 1);
      var eased = 1 - Math.pow(1 - p, 3);
      label.textContent = (TARGET * eased).toFixed(2) + '%';
      if (p < 1) requestAnimationFrame(step);
      else label.textContent = TARGET.toFixed(2) + '%';
    }
    requestAnimationFrame(step);
  }
  function wirePurityWidgets(){
    var widgets = document.querySelectorAll('[data-purity-widget]');
    if (!widgets.length) return;
    if ('IntersectionObserver' in window) {
      var io = new IntersectionObserver(function(entries){
        entries.forEach(function(e){ if (e.isIntersecting) animate(e.target); });
      }, { threshold: 0.4 });
      widgets.forEach(function(w){ io.observe(w); });
    } else {
      widgets.forEach(animate);
    }
  }
  wirePurityWidgets(); setTimeout(wirePurityWidgets, 300); setTimeout(wirePurityWidgets, 1000);
})();
